import {createPlaybackClock} from './playback-clock.js';
import {createEngine,BASE_MULTIPLIERS,FREE_MULTIPLIERS,DEFAULT_PAYTABLE,allowedBets,maxBet} from './engine.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const engine=createEngine();const suits={S:'♠',H:'♥',C:'♣',D:'♦'};
const saved=(()=>{try{return JSON.parse(localStorage.getItem('gala-carrot-v1'))||{}}catch{return{}}})();
let balance=Number.isFinite(saved.balance)?saved.balance:2000,bet=20,board=engine.deal(),busy=false,speed=0,soundOn=false,audio,free=0,freeTotal=0,lastWin=0,auto=null,stopRequested=false,round=0,featureResolver=null,isDemo=false;
const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});const durations=[1,.5,0];const playback=createPlaybackClock();
const wait=ms=>playback.wait(ms);
function msg(t){$('#message').textContent=t}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function tone(freq=600,d=.08){if(!soundOn)return;try{audio??=new AudioContext();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.start();o.stop(audio.currentTime+d)}catch{}}
function cardHTML(c){
 const special=c.symbol==='CARROT'||c.symbol==='ANGEL'||c.symbol==='DEVIL';
 const path=c.symbol==='CARROT'?'carrot-bonus.png':c.symbol==='ANGEL'?'wild-angel.png':c.symbol==='DEVIL'?'wild-devil.png':`card-${c.gold?'gold':'normal'}-${c.symbol}.png`;
 const label=c.symbol==='CARROT'?'CARROT 免費遊戲符號':c.symbol==='ANGEL'?'天使小 WILD':c.symbol==='DEVIL'?'惡魔大 WILD':`${c.gold?'金牌 ':''}${c.symbol}`;
 return `<div class="card ${special?'special':''} ${c.gold?'gold':''}"><img class="art-card" src="assets/art/${path}" alt="${label}">${c.gold&&!special?'<img class="gold-frame-art" src="assets/art/card-gold-overlay.png" alt="" aria-hidden="true">':''}</div>`;
}
function render(changes=[],kind=''){const nodes=$$('#board .cell');board.forEach((c,i)=>{let n=nodes[i];if(!n){n=document.createElement('div');$('#board').append(n)}n.className='cell '+(c.symbol==='CARROT'?'carrot ':'')+(changes.includes(i)?kind:'');n.dataset.index=i;n.setAttribute('aria-label',`${Math.floor(i/5)+1}行${i%5+1}列 ${c.gold?'金牌 ':''}${c.symbol}`);const faceKey=c.symbol+':'+Number(c.gold);if(n.dataset.face!==faceKey){n.innerHTML=cardHTML(c);n.dataset.face=faceKey}n.style.setProperty('--delay',`calc(${(i%5)*35+Math.floor(i/5)*15}ms * var(--motion-scale,1))`);n.style.setProperty('--fall-duration',`calc(400ms * var(--motion-scale,1))`);if(kind==='fall'&&changes.includes(i)){const source=$$('.mouth')[i%5].getBoundingClientRect(),target=n.getBoundingClientRect();n.style.setProperty('--drop-start',`${source.bottom-target.top-target.height}px`);n.style.setProperty('--deal-shift',`${source.x+source.width/2-target.x-target.width/2}px`)}});update()}
function fitAmounts(){for(const amount of $$('.balance-bar strong')){amount.style.fontSize='';amount.title=amount.textContent;const width=amount.clientWidth;if(width&&amount.scrollWidth>width){const size=parseFloat(getComputedStyle(amount).fontSize);amount.style.fontSize=Math.max(11,Math.floor(size*width/amount.scrollWidth))+'px'}}}
function update(){playback.setScale(durations[speed]);document.documentElement.style.setProperty('--motion-scale',durations[speed]);$('#speed').dataset.speed=String(speed);$('#sound').setAttribute('aria-pressed',String(soundOn));const tiers=allowedBets(balance);if(!busy&&!free&&bet>maxBet(balance))bet=tiers.at(-1)||1;$('#balance').textContent=fmt(balance);$('#bet').textContent=fmt(bet);$('#win').textContent=fmt(lastWin);fitAmounts();$('#spin').disabled=busy||free>0||bet>maxBet(balance);$('#spin').classList.toggle('busy',busy);$('#plus').disabled=busy||free>0;$('#minus').disabled=busy||free>0;$('#auto').classList.toggle('on',!!auto);$('#auto small').textContent=auto?String(auto.left):'AUTO';$('#auto').setAttribute('aria-label',auto?'停止自動遊戲':'自動遊戲設定');$('#speed small').textContent=['正常','2×','MAX'][speed];$('#speed').setAttribute('aria-label','切換遊戲速度，目前'+['正常','快速','極速'][speed]);$('#speed').classList.toggle('on',speed>0);$('#freePill').hidden=!free;$('#freePill').textContent=`免費 ${free} 次`;$('#modeLabel').textContent=free?'THE CARROT CELEBRATION':'LET THE CARROTS FALL';$('#freeLabel').textContent=free?'FREE GAME · 金色時刻':'1024 WAYS · 金牌連鎖'}
function setMultiplier(step,isFree){const vals=isFree?FREE_MULTIPLIERS:BASE_MULTIPLIERS;$('#multipliers').innerHTML=vals.map((v,i)=>`<span class="${i===Math.min(step,3)?'active':''}">×${v}</span>`).join('')}
function save(){localStorage.setItem('gala-carrot-v1',JSON.stringify({balance}))}
function openModal(html){$('#modal').classList.remove('auto-modal');$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){if(featureResolver){const r=featureResolver;featureResolver=null;r()}$('#modal').close()}
$('#closeModal').onclick=close;$('#modal').addEventListener('cancel',()=>{if(featureResolver){const r=featureResolver;featureResolver=null;r()}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});
function feature(n,extra=false){return new Promise(resolve=>{featureResolver=resolve;openModal(`<div class="feature-carrots">${[1,2,3].map(()=>'<img src="assets/art/carrot-bonus.png" alt="CARROT">').join('')}</div><div class="feature-title">${extra?'＋'+n:n} FREE SPINS</div><p style="text-align:center">${extra?'金蘿蔔再度登場，免費次數已追加。':'三個 CARROT，開啟你的金色時刻。'}<br>免費遊戲倍率：×2、×4、×6、×10</p><div class="btn-row"><button class="btn primary" id="featureGo">${extra?'繼續':'開始免費遊戲'}</button></div>`);$('#featureGo').onclick=close})}
function drawRays(copies){$('#rays').innerHTML='';for(const c of copies){let cells=$$('#board .cell'),a=cells[c.source].getBoundingClientRect(),b=cells[c.index].getBoundingClientRect(),p=$('.board-shell').getBoundingClientRect(),dx=b.x-a.x,dy=b.y-a.y;let n=document.createElement('div');n.className='ray';n.style.cssText=`left:${a.x-p.x+a.width/2}px;top:${a.y-p.y+a.height/2}px;width:${Math.hypot(dx,dy)}px;transform:rotate(${Math.atan2(dy,dx)}rad)`;$('#rays').append(n)}}
async function spin({demo=false}={}){if(busy)return;const isFree=free>0;if(!isFree&&!demo&&bet>maxBet(balance)){toast('每次下注最多為現有蘿蔔的 10%');return}busy=true;stopRequested=false;isDemo=demo;lastWin=0;round++;const roundBet=bet;let carrotsAwarded=false,startedFree=false,won=0;const oldBalance=balance;
if(isFree)free--;else if(!demo)balance=Math.round((balance-roundBet)*100)/100;
update();setMultiplier(0,isFree);msg(demo?'動畫試映 · 不扣除蘿蔔':isFree?'免費遊戲進行中…':'牌已發出，幸運正在路上。');tone(350);
$$('#board .cell').forEach(n=>n.classList.add('out'));await wait(260);board=engine.deal();
if(demo){board=Array.from({length:20},(_,i)=>({symbol:['A','K','Q','S','D'][i%5],gold:false}));board[0]={symbol:'J',gold:false};board[6]={symbol:'J',gold:true};board[12]={symbol:'J',gold:false};board[15]={symbol:'CARROT',gold:false};board[18]={symbol:'CARROT',gold:false}}
$('.dealer').classList.add('dealing');render([...Array(20).keys()],'fall');await wait(750);$('.dealer').classList.remove('dealing');
let count=board.filter(c=>c.symbol==='CARROT').length;if(count>=2&&speed<2){$('.board-shell').classList.add('suspense');$$('#board .carrot').forEach(n=>n.classList.add('anticipate'));msg(count>=3?'金蘿蔔登場！':'兩個 CARROT，等待最後一列…');tone(780,.2);await wait(850);$('.board-shell').classList.remove('suspense');render()}
try{for(let step=0;;step++){
const vals=isFree?FREE_MULTIPLIERS:BASE_MULTIPLIERS,mult=vals[Math.min(step,3)];setMultiplier(step,isFree);
count=board.filter(c=>c.symbol==='CARROT').length;
if(count>=3&&!carrotsAwarded&&!demo){carrotsAwarded=true;const n=isFree?5:10;free+=n;if(!isFree){startedFree=true;freeTotal=0}if(auto?.onFeature){auto=null;toast('已觸發免費遊戲，自動付費旋轉已停止')}update();$$('#board .carrot').forEach(n=>n.classList.add('bounce'));await feature(n,isFree);render()}
const result=engine.evaluate(board,roundBet,mult);if(result.total<=0)break;
won=Math.round((won+result.total)*100)/100;lastWin=won;msg(`連鎖 ${step+1} · ${result.wins.map(w=>`${w.ways} ways`).join(' + ')} · ×${mult}`);
$$('#board .cell').forEach((n,i)=>n.classList.add(result.positions.includes(i)?'hit':'dim'));tone(500+Math.min(step,8)*90,.15);$('#winPop').textContent=`＋${fmt(result.total)}`;$('#winPop').classList.remove('show');void $('#winPop').offsetWidth;$('#winPop').classList.add('show');update();await wait(700);
const next=engine.resolveStep(board,roundBet,mult);next.replacements.forEach(c=>$$('#board .cell')[c.index].classList.add('out'));await wait(300);board=next.board;render(next.replacements.map(c=>c.index),'fall');next.conversions.forEach(c=>$$('#board .cell')[c.index].classList.add('turn'));await wait(450);
if(next.copies.length){msg('惡魔 WILD · 金色力量擴散');drawRays(next.copies);next.copies.forEach(c=>$$('#board .cell')[c.index].classList.add('copy'));tone(900,.2);await wait(650);$('#rays').innerHTML=''}
await wait(400);render();if(step>12){msg('連鎖進行中…');await new Promise(r=>setTimeout(r,0))}
}
if(!demo){balance=Math.round((balance+won)*100)/100;if(isFree)freeTotal=Math.round((freeTotal+won)*100)/100;save()}else balance=oldBalance;
lastWin=won;render();if(won>=roundBet*10&&!demo){openModal(`<div class="feature-title">${won>=roundBet*30?'EPIC WIN':'BIG WIN'}</div><p class="reward-amount"><img class="currency-inline" src="assets/carrot.png" alt="蘿蔔"> ${fmt(won)}</p><p style="text-align:center">金色時刻，屬於你的蘿蔔。</p><div class="btn-row"><button class="btn primary" id="rewardGo">收下獎勵</button></div>`);await new Promise(r=>{featureResolver=r;$('#rewardGo').onclick=close})}
if(isFree&&free===0){openModal(`<div class="feature-title">TOTAL WIN</div><p class="reward-amount"><img class="currency-inline" src="assets/carrot.png" alt="蘿蔔"> ${fmt(freeTotal)}</p><p style="text-align:center">免費遊戲結束，回到普通遊戲。</p><div class="btn-row"><button class="btn primary" id="totalGo">繼續</button></div>`);await new Promise(r=>{featureResolver=r;$('#totalGo').onclick=close});freeTotal=0}
msg(demo?'試映結束 · 沒有扣除或增加蘿蔔':won?`本局獲得 ${fmt(won)} 蘿蔔`:'本局沒有中獎。');
if(auto&&!isFree){auto.left--;if(auto.left<=0||won/roundBet>=auto.ratio||balance<auto.lower||balance>auto.upper||roundBet>maxBet(balance)){auto=null;msg('自動遊戲已停止。')}}
}catch(e){console.error(e);auto=null;msg('本局演出發生問題，請重設試玩。');toast('演出中斷，已停止自動遊戲')}finally{busy=false;isDemo=false;$('#winPop').classList.remove('show');$('#rays').innerHTML='';$('.dealer').classList.remove('dealing');$('.board-shell').classList.remove('suspense');update()}
if(free>0)wait(400).then(()=>spin());else if(auto&&!stopRequested){if(bet!==roundBet){auto=null;update();toast('餘額變更，請重新選擇下注')}else wait(650).then(()=>{if(auto&&!busy)spin()})}
}
$('#spin').onclick=()=>spin();$('#speed').onclick=()=>{speed=(speed+1)%3;update();toast(['正常速度','2× 快速模式','MAX：略過過場動畫'][speed]);tone(500+speed*200)};
function adjust(d){if(busy||free)return;const tiers=allowedBets(balance);let i=tiers.indexOf(bet);let next=tiers[Math.max(0,Math.min(tiers.length-1,i+d))];if(!next){toast('蘿蔔不足以支持最低下注');return}if(d>0&&next===bet)toast(`最高下注 ${fmt(maxBet(balance))} 蘿蔔（餘額的 10%）`);bet=next;update()}
$('#minus').onclick=()=>adjust(-1);$('#plus').onclick=()=>adjust(1);$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound').textContent=soundOn?'♫':'♩';$('#sound').setAttribute('aria-pressed',String(soundOn));tone();toast(soundOn?'音效開啟':'音效關閉')};
$('#auto').onclick=()=>{if(auto){auto=null;stopRequested=true;update();toast('本局完成後停止自動旋轉');return}if(busy||free){toast('請等待本局結束');return}openModal(`<h2>Auto Play</h2><p>設定連續旋轉次數及停止條件。</p><div class="chips">${[10,20,30,40,50].map(n=>`<button data-spins="${n}" class="${n===10?'selected':''}">${n}</button>`).join('')}</div><div class="form-row"><span>旋轉次數</span><input id="autoCount" aria-label="自動旋轉次數" type="number" value="10" min="1" max="500"></div><div class="form-row"><label><input id="ratioOn" type="checkbox">單局獎勵達下注倍數</label><input id="ratioVal" aria-label="單局獎勵倍數停止上限" type="number" value="100" min="1"></div><div class="form-row"><label><input id="lowerOn" type="checkbox">餘額低於</label><input id="lowerVal" aria-label="蘿蔔餘額下限" type="number" value="${Math.floor(balance*.5)}" min="0"></div><div class="form-row"><label><input id="upperOn" type="checkbox">餘額高於</label><input id="upperVal" aria-label="蘿蔔餘額上限" type="number" value="${Math.ceil(balance*1.5)}" min="0"></div><div class="form-row"><label><input id="featureOn" type="checkbox" checked>觸發免費遊戲後停止付費旋轉</label></div><div class="modal-note">下注最多為餘額10%；停止於當局結束後生效。</div><div class="btn-row"><button class="btn" id="autoCancel">取消</button><button class="btn primary" id="autoStart">開始</button></div>`);$('#modal').classList.add('auto-modal');$$('[data-spins]').forEach(b=>b.onclick=()=>{$('#autoCount').value=b.dataset.spins;$$('[data-spins]').forEach(n=>n.classList.toggle('selected',n===b))});$('#autoCancel').onclick=close;$('#autoStart').onclick=()=>{const count=Number($('#autoCount').value);if(!Number.isInteger(count)||count<1||count>500){toast('請輸入 1–500 次');return}const num=s=>Number($(s).value);if(['#ratioVal','#lowerVal','#upperVal'].some(s=>!Number.isFinite(num(s))||num(s)<0)){toast('停止條件請輸入有效數值');return}auto={left:count,ratio:$('#ratioOn').checked?num('#ratioVal'):Infinity,lower:$('#lowerOn').checked?num('#lowerVal'):-Infinity,upper:$('#upperOn').checked?num('#upperVal'):Infinity,onFeature:$('#featureOn').checked};if(auto.lower>=auto.upper){toast('下限須低於上限');return}close();spin()}};
const rules=`<h3>怎樣中獎？</h3><p>盤面為 5 列 × 4 行，共 1024 ways。相同符號由最左列開始，連續出現在至少 3 列即可中獎，不需要同一行。各列可用位置數相乘，就是中獎 ways。</p><h3>金牌及 WILD</h3><p>金牌只會出現在第 2–4 列。金牌參與中獎後轉成天使或惡魔 WILD。WILD 可替代普通符號，不能替代 CARROT。惡魔會將第 2–5 列的 1–4 個合資格普通牌位轉為惡魔 WILD；不取代 CARROT 或已有 WILD。</p><h3>消除與倍率</h3><p>中獎普通牌消除，新牌由上方落入原空位。未中獎牌留在原位。普通遊戲倍率依序 ×1、×2、×3、×5；下一次付費旋轉重置。</p><h3>CARROT 與免費遊戲</h3><p>同一盤面有 3 個或以上 CARROT，獲得 10 次免費遊戲；免費遊戲中再出現 3 個或以上，加 5 次。免費倍率為 ×2、×4、×6、×10。同一次旋轉只發放一次 CARROT 獎勵，避免保留符號重複觸發。</p><h3>蘿蔔與下注</h3><p>每次付費下注最多為當時餘額的 10%。免費遊戲沿用觸發局下注額，不扣蘿蔔。Auto 每次開始前重新檢查上限。</p><p class="modal-note">私人試玩版：測試蘿蔔只保存在此瀏覽器，不能充值、兌現或轉移。隨機權重及賠付表未作商用數學校準；不代表 JILI 原版的 RTP 或派彩分佈。</p>`;
function help(tab='rules'){openModal(`<h2>玩法與計算</h2><div class="tabs"><button id="rulesTab" class="${tab==='rules'?'active':''}">玩法</button><button id="payTab" class="${tab==='pay'?'active':''}">賠付與例子</button></div>${tab==='rules'?rules:`<p class="modal-note">以下為目前試玩參考表，尚未確認為 JILI 官方遊戲內賠付表。數值以本版本下注單位計算，不宣稱精確復刻。</p><table><thead><tr><th>符號</th><th>3列</th><th>4列</th><th>5列</th></tr></thead><tbody>${Object.entries(DEFAULT_PAYTABLE).map(([s,v])=>`<tr><td>${suits[s]||s}</td>${v.map(n=>`<td>×${n}</td>`).join('')}</tr>`).join('')}</tbody></table><h3>計算方法</h3><p>同符號獎勵＝賠付值 × 中獎 ways × 下注額 × 當前倍率。多種符號中獎分別計算再相加，金額以兩位小數記錄。</p><p>例：下注 20、A 連續 3 列各有 1、2、1 個可用位置，ways＝1×2×1＝2。當前倍率 ×2，獎勵＝0.5×2×20×2＝40 蘿蔔。</p><p>參考：<a href="https://jiligames.com/PlusIntro/49?showGame=false" target="_blank" rel="noopener">JILI 原版介紹</a>。</p>`}<div class="btn-row"><button class="btn" id="replayTutorial">重看教學</button><button class="btn primary" id="helpDone">明白</button></div>`);$('#rulesTab').onclick=()=>help('rules');$('#payTab').onclick=()=>help('pay');$('#helpDone').onclick=close;$('#replayTutorial').onclick=()=>tutorial(0)}
$('#help').onclick=()=>help();$('#settings').onclick=()=>{openModal(`<h2>你的遊戲節奏</h2><p>隨時調整速度，派牌結果不會因此改變。</p><div class="chips">${['正常','快速','極速'].map((s,i)=>`<button data-speed="${i}" class="${i===speed?'selected':''}">${s}</button>`).join('')}</div><div class="form-row"><label><input type="checkbox" id="soundCheck" ${soundOn?'checked':''}>遊戲音效</label></div><p class="modal-note">下注最多為蘿蔔餘額的10%。試玩餘額保存在此瀏覽器。</p><div class="btn-row"><button class="btn" id="resetTestBalance">重設蘿蔔</button><button class="btn primary" id="settingsDone">完成</button></div>`);$$('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);$$('[data-speed]').forEach(n=>n.classList.toggle('selected',n===b));update()});$('#soundCheck').onchange=e=>{soundOn=e.target.checked;update();tone()};$('#settingsDone').onclick=close;$('#resetTestBalance').onclick=resetPlaytest};
const lessons=[['不同位置，也能連成幸運','由最左列開始，至少連續 3 列出現同一符號即可中獎，不必在同一行。','<div class="tutorial-cards"><img src="assets/art/card-normal-H.png" alt="紅心"><img style="margin-top:15px" src="assets/art/card-normal-H.png" alt="紅心"><img style="margin-top:30px" src="assets/art/card-normal-H.png" alt="紅心"></div>'],['金牌翻面，WILD 登場','金牌中獎後轉成天使或惡魔。天使替代普通牌，惡魔還可擴散到其他合資格牌位。','<div class="feature-carrots"><img src="assets/art/wild-angel.png" alt="天使小WILD"><img src="assets/art/wild-devil.png" alt="惡魔大WILD"></div>'],['三個 CARROT，金色時刻','同一盤面出現至少 3 個 CARROT，即可進入 10 次免費遊戲。免費遊戲內可追加次數。','<div class="feature-carrots">'+[1,2,3].map(()=>'<img src="assets/art/carrot-bonus.png" alt="CARROT">').join('')+'</div>'],['選好節奏，開始你的 Gala','下注不超過蘿蔔餘額 10%。AUTO 可設定停止條件；SPEED 可在正常、快速、極速間切換。教學不扣蘿蔔。','<div class="tutorial-cards"><img src="assets/carrot.png" alt="下注最多餘額10%"><img src="assets/art/ui/buttons/auto/normal.svg" alt="AUTO"><img src="assets/art/ui/buttons/speed-normal/normal.svg" alt="SPEED"></div>']];
function tutorial(i){const [title,text,art]=lessons[i];openModal(`<h2>${title}</h2>${art}<p>${text}</p><div class="tutorial-progress">${lessons.map((_,j)=>`<i class="${j===i?'active':''}"></i>`).join('')}</div><div class="btn-row"><button class="btn" id="skipLesson">跳過</button><button class="btn primary" id="nextLesson">${i===3?'開始遊戲':'下一步'}</button></div>`);const done=()=>{localStorage.setItem('gala-carrot-tutorial','1');close()};$('#skipLesson').onclick=done;$('#nextLesson').onclick=()=>i===3?done():tutorial(i+1)}
const resetPlaytest=()=>{if(busy||free){toast('請先完成目前遊戲');return}openModal('<h2>重新開始試玩？</h2><p>將本瀏覽器的測試蘿蔔重設為 2,000，並停止 Auto。</p><div class="btn-row"><button class="btn" id="cancelReset">取消</button><button class="btn primary" id="confirmReset">重設</button></div>');$('#cancelReset').onclick=close;$('#confirmReset').onclick=()=>{auto=null;balance=2000;bet=20;lastWin=0;save();render();close();msg('新的金色時刻，開始吧。')}};
const demoAnimation=()=>{if(busy||free){toast('請先完成目前遊戲');return}auto=null;spin({demo:true})};
$('.mouths').innerHTML=Array.from({length:5},()=>'<div class="mouth"><img src="assets/art/v2/dealer-back-fit.png" alt=""></div>').join('');
board=['J','K','Q','A','S','H','S','D','C','J','Q','D','K','H','D','C','J','H','A','K'].map((symbol,i)=>({symbol,gold:[1,12,18].includes(i)}));render();setMultiplier(0,false);
if(!localStorage.getItem('gala-carrot-tutorial'))setTimeout(()=>tutorial(0),700);
function alignDealer(){const table=$('.board-shell');$('.game').style.setProperty('--board-width',table.getBoundingClientRect().width+'px')}
new ResizeObserver(alignDealer).observe($('.board-shell'));alignDealer();
window.addEventListener('resize',()=>{fitAmounts();alignDealer()});document.fonts.ready.then(fitAmounts);
window.galaDebug={getState:()=>({balance,bet,board:structuredClone(board),free,busy,speed,auto}),spin,help,tutorial,demoAnimation,resetPlaytest};
